from decimal import Decimal, ROUND_HALF_UP


def tax(amount, rate):
    """Tax on an invoice amount, rounded half up to the cent per FIN-12."""
    cents = (Decimal(str(amount)) * Decimal(str(rate))).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP
    )
    return float(cents)

